import os
import sqlite3
import time
import sys
from datetime import datetime, timedelta

TOKEN_FILE = "tokens.txt"
DB_FILE = "data.db"
RATE_LIMIT = 5
RATE_LIMIT_WINDOW = 60  # seconds

class RateLimiter:
    def __init__(self):
        self.token_data = {}
        self.load_token_data()

    def load_token_data(self):
        if os.path.exists(TOKEN_FILE):
            with open(TOKEN_FILE, 'r') as f:
                for line in f:
                    token = line.strip()
                    if token:
                        self.token_data[token] = {
                            'queries': [],
                            'last_updated': datetime.now()
                        }

    def save_token_data(self):
        with open(TOKEN_FILE, 'w') as f:
            for token, data in self.token_data.items():
                f.write(f"{token}\n")

    def check_rate_limit(self, token):
        if token not in self.token_data:
            return False

        current_time = datetime.now()
        data = self.token_data[token]

        # Remove queries older than the current minute
        while data['queries'] and data['queries'][0] < current_time.replace(second=0, microsecond=0):
            data['queries'].pop(0)

        # Check if we've exceeded the limit
        if len(data['queries']) >= RATE_LIMIT:
            return False

        data['queries'].append(current_time)
        self.save_token_data()
        return True

def verify_token():
    token = os.getenv('DB_TOKEN')
    if not token:
        print("ACCESS_DENIED")
        sys.exit(1)

    if token not in RateLimiter().token_data:
        print("ACCESS_DENIED")
        sys.exit(1)

    return token

def execute_query(token):
    rate_limiter = RateLimiter()
    if not rate_limiter.check_rate_limit(token):
        print("RATE_LIMIT_EXCEEDED")
        sys.exit(2)

    try:
        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()
        query = sys.argv[1].strip('"')
        cursor.execute(query)
        rows = cursor.fetchall()

        for row in rows:
            print(','.join(str(item) for item in row))

        conn.close()
    except sqlite3.Error as e:
        print(f"QUERY_ERROR: {str(e)}")
        sys.exit(3)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: DB_TOKEN=<token> python dbcli.py \"<sql query>\"")
        sys.exit(1)

    token = verify_token()
    execute_query(token)

import os
import sys
import sqlite3
import time
from datetime import datetime, timedelta

def load_tokens():
    try:
        with open('tokens.txt', 'r') as f:
            return {line.strip() for line in f}
    except (IOError, OSError):
        return set()

def validate_token():
    token = os.getenv('DB_TOKEN')
    if not token:
        print('ACCESS_DENIED')
        sys.exit(1)
    tokens = load_tokens()
    if token not in tokens:
        print('ACCESS_DENIED')
        sys.exit(1)
    return token

def get_throttling_data():
    try:
        with open('throttling.db', 'r+b') as f:
            conn = sqlite3.connect(':memory:')
            cursor = conn.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS throttling (
                    token TEXT PRIMARY KEY,
                    minute INTEGER,
                    count INTEGER
                )
            ''')
            cursor.execute('SELECT * FROM throttling')
            return cursor.fetchall()
    except (IOError, OSError):
        return []

def save_throttling_data(token, minute, count):
    try:
        with open('throttling.db', 'r+b') as f:
            conn = sqlite3.connect(':memory:')
            cursor = conn.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS throttling (
                    token TEXT PRIMARY KEY,
                    minute INTEGER,
                    count INTEGER
                )
            ''')
            cursor.execute('DELETE FROM throttling WHERE token = ?', (token,))
            cursor.execute('INSERT INTO throttling (token, minute, count) VALUES (?, ?, ?)',
                          (token, minute, count))
            conn.commit()
            f.seek(0)
            f.truncate()
            f.write(b'')
            f.write(str(cursor.rowcount).encode())
    except (IOError, OSError):
        pass

def check_rate_limit(token):
    current_time = int(time.time())
    minute = current_time // 60
    existing_data = get_throttling_data()
    for row in existing_data:
        if row[0] == token and row[1] == minute:
            return row[2]
    return 0

def execute_query(token):
    if check_rate_limit(token) >= 5:
        print('RATE_LIMIT_EXCEEDED')
        sys.exit(2)

    current_time = int(time.time())
    minute = current_time // 60
    new_count = check_rate_limit(token) + 1
    save_throttling_data(token, minute, new_count)

    try:
        conn = sqlite3.connect('data.db')
        cursor = conn.cursor()
        cursor.execute(sys.argv[1])
        rows = cursor.fetchall()
        conn.close()
        if rows:
            for row in rows:
                print(','.join(str(x) for x in row))
    except sqlite3.Error as e:
        print(f'QUERY_ERROR: {str(e)}')
        sys.exit(3)

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: DB_TOKEN=<token> python dbcli.py "<sql query>"')
        sys.exit(1)
    token = validate_token()
    execute_query(token)
